140	          gap={12}
141	          background={Colors.primary}
142	          animations={controlsAnimation.animations}
143	          pointerEvents={showControls ? "auto" : "none"}
144	        >
145	          <BlurGradientOverlay />
146	          <Block zIndex={2}>
147	            <Button.Wrapper onPress={onClose}>
148	              <Text font="InstrumentSans-Semibold" color={Colors.white}>
149	                Close
150	              </Text>
151	            </Button.Wrapper>
152	          </Block>
153	        </Block>
154	
155	        <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
156	          {isLoading && !hasError && (
157	            <Block
158	              absolute
159	              width={SCREEN_WIDTH}
160	              height={SCREEN_HEIGHT}
161	              align="center"
162	              justify="center"
163	              zIndex={5}
164	              background={Colors.white10}
165	            >
166	              <Loading isFullScreen={false} />
167	            </Block>
168	          )}
169	
170	          {hasError ? (
171	            <Block
172	              width={SCREEN_WIDTH}
173	              height={SCREEN_HEIGHT}
174	              align="center"
175	              justify="center"
176	            >
177	              <Text color={Colors.white}>Failed to load image</Text>
178	              <TouchableOpacity
179	                onPress={handleRetry}
180	                style={styles.retryButton}
181	              >
182	                <Text size={TextSize.small} color={Colors.white}>
183	                  Tap to retry
184	                </Text>
185	              </TouchableOpacity>
186	            </Block>
187	          ) : localUri ? (
188	            <ImageZoom
189	              key={localUri}
190	              uri={localUri}
191	              minScale={1}
192	              maxScale={5}
193	              maxPanPointers={2}
194	              isPanEnabled
195	              isPinchEnabled
196	              isDoubleTapEnabled
197	              isSingleTapEnabled
198	              style={{ width: SCREEN_WIDTH, height: SCREEN_HEIGHT }}
199	              onLoad={handleImageLoad}
200	              onError={handleImageError}
201	              onSingleTap={handleSingleTap}
202	            />
203	          ) : null}
204	        </Block>
205	      </Block>
206	    </Modal>
207	  );
208	};
